function maximumLength(nums) {
  const count = new Map();
  for (const num of nums) {
    count.set(num, (count.get(num) || 0) + 1);
  }
  const ones = count.get(1) || 0;
  let best = ones % 2 === 1 ? ones : Math.max(ones - 1, 0);
  for (const value of count.keys()) {
    if (value === 1) {
      continue;
    }
    let current = value;
    let length = 0;
    while (count.has(current) && count.get(current) >= 2) {
      length += 2;
      current = current * current;
    }
    if (count.has(current)) {
      length += 1;
    } else {
      length -= 1;
    }
    best = Math.max(best, length);
  }
  return best;
}

