function maximumLength(nums) {
  // Try every subset and test whether its sorted values match the sorted pattern built from its smallest value.
  const n = nums.length;
  let best = 0;
  for (let mask = 1; mask < (1 << n); mask++) {
    const picked = [];
    for (let i = 0; i < n; i++) if (mask & (1 << i)) picked.push(nums[i]);
    if (picked.length % 2 === 0 || picked.length <= best) continue;
    picked.sort((p, q) => p - q);
    const half = (picked.length - 1) / 2;
    const pattern = [];
    let power = picked[0];
    for (let level = 0; level < half; level++) {
      pattern.push(power, power);
      power = power * power;
    }
    pattern.push(power);
    pattern.sort((p, q) => p - q);
    if (pattern.every((v, i) => v === picked[i])) best = picked.length;
  }
  return best;
}

