function generate(rand, size) {
  const large = size === 'large';
  const n = large ? 2000 : 2 + Math.floor(rand() * 9);
  const pool = [1];
  const bases = large ? 40 : 4;
  for (let b = 2; b <= bases + 1; b++) {
    for (let v = b; v <= 1000000000; v = v * v) pool.push(v);
  }
  const oneRate = large ? [0, 0.002, 0.1][Math.floor(rand() * 3)] : 0.15;
  const nums = [];
  for (let i = 0; i < n; i++) {
    const r = rand();
    if (r < oneRate) nums.push(1);
    else if (r < 0.8) nums.push(pool[Math.floor(rand() * pool.length)]);
    else nums.push(1 + Math.floor(rand() * (large ? 1000000000 : 20)));
  }
  return [nums];
}
